#!/usr/bin/env python3
"""Verify package exact set, manifest payload entries, and sums self binding."""
from __future__ import annotations

import hashlib
import json
from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]
MANIFEST = ROOT / "10_MANIFEST.json"
SUMS = ROOT / "11_SHA256SUMS"


def digest(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def main() -> int:
    manifest = json.loads(MANIFEST.read_text(encoding="utf-8"))
    entries = {item["path"]: item for item in manifest["files"]}
    payload = {
        path.relative_to(ROOT).as_posix(): path
        for path in ROOT.rglob("*") if path.is_file()
        and path.relative_to(ROOT).as_posix() not in {"10_MANIFEST.json", "11_SHA256SUMS"}
    }
    forbidden = [
        name for name in payload
        if "__pycache__" in name.split("/") or ".pytest_cache" in name.split("/")
        or name.endswith(".pyc")
    ]
    if forbidden:
        raise SystemExit(f"forbidden generated files: {forbidden}")
    if set(entries) != set(payload):
        raise SystemExit("manifest payload exact-set mismatch")
    for name, path in payload.items():
        item = entries[name]
        if path.stat().st_size != item["bytes"] or digest(path) != item["sha256"]:
            raise SystemExit(f"payload mismatch: {name}")
    sums: dict[str, str] = {}
    raw = SUMS.read_text(encoding="utf-8")
    if "\r" in raw:
        raise SystemExit("11_SHA256SUMS must use LF")
    for line in raw.splitlines():
        value, name = line.split("  ", 1)
        if name in sums:
            raise SystemExit(f"duplicate sums path: {name}")
        sums[name] = value
    expected = dict(payload)
    expected["10_MANIFEST.json"] = MANIFEST
    if set(sums) != set(expected):
        raise SystemExit("sums exact-set mismatch or manifest not bound")
    for name, path in expected.items():
        if sums[name] != digest(path):
            raise SystemExit(f"sums mismatch: {name}")
    print(f"PACKAGE_VERIFY=PASS")
    print(f"MANIFEST_SHA256={digest(MANIFEST)}")
    print(f"PACKAGE_SELF_SHA256={digest(SUMS)}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

